function tryLoadFromURL() {
  try {
    const p = new URLSearchParams(location.search);
    const raw = p.get('data');
    if (!raw) return false;
    const json = JSON.parse(decodeURIComponent(escape(atob(raw.replace(/-/g, '+').replace(/_/g, '/')))));
    if (!json || !Array.isArray(json.tasks) || !json.tasks.length) return false;
    document.getElementById('projName').value = json.name || "Project";
    if (json.start) document.getElementById('projStart').value = json.start;
    if (json.hours) document.getElementById('hoursDay').value = json.hours;
    tasks = json.tasks.map((t, i) => ({
      id: Number(t.id ?? i + 1),
      name: String(t.name || "Task"),
      level: Math.max(1, Math.min(6, Number(t.level) || 1)),
      days: Math.max(0, Number(t.days) || 0),
      preds: (typeof t.preds === 'string' ? t.preds.split(',') : (t.preds || []))
        .map(x => parseInt(String(x).trim())).filter(n => !isNaN(n)),
      res: String(t.res || "")
    }));
    nextId = Math.max(...tasks.map(t => t.id)) + 1;
    render();
    toast('Loaded “' + (json.name || 'schedule') + '” from your collection');
    return true;
  } catch (e) { return false; }
}

