/* ============================ IMPORT — MSPDI XML ============================ */
// ISO-8601 duration ("PT40H0M0S", "P2DT4H") → whole working days
function durToDays(s, hpd) {
  if (!s) return 1;
  const m = String(s).match(/P(?:([\d.]+)D)?(?:T(?:([\d.]+)H)?(?:([\d.]+)M)?(?:([\d.]+)S)?)?/);
  if (!m) return 1;
  const d = +(m[1] || 0), h = +(m[2] || 0), mi = +(m[3] || 0), sec = +(m[4] || 0);
  const totalH = d * hpd + h + mi / 60 + sec / 3600;
  return Math.max(0, Math.round(totalH / hpd));
}

function importMSPDI(text) {
  const doc = new DOMParser().parseFromString(text, 'application/xml');
  if (doc.getElementsByTagName('parsererror').length) throw new Error('the file is not valid XML');
  const root = doc.documentElement;
  if (!root || !/project/i.test(root.localName || root.nodeName)) throw new Error('not a Microsoft Project XML file');
  const first = (p, n) => { const e = p.getElementsByTagNameNS('*', n)[0]; return e ? e.textContent.trim() : ''; };

  const projName = first(root, 'Title') || first(root, 'Name').replace(/\.xml$/i, '') || 'Imported project';
  const hpd = Math.max(1, Math.round((parseInt(first(root, 'MinutesPerDay')) || 480) / 60));
  const startAttr = first(root, 'StartDate');

  // resources: UID -> name
  const resById = {};
  [...root.getElementsByTagNameNS('*', 'Resource')].forEach(r => {
    const uid = first(r, 'UID'), nm = first(r, 'Name');
    if (uid && nm) resById[uid] = nm;
  });
  // assignments: taskUID -> "res, res"
  const taskRes = {};
  [...root.getElementsByTagNameNS('*', 'Assignment')].forEach(a => {
    const tu = first(a, 'TaskUID'), ru = first(a, 'ResourceUID');
    if (tu && resById[ru]) taskRes[tu] = taskRes[tu] ? taskRes[tu] + ', ' + resById[ru] : resById[ru];
  });

  const out = [];
  [...root.getElementsByTagNameNS('*', 'Task')].forEach(t => {
    const name = first(t, 'Name');
    const level = parseInt(first(t, 'OutlineLevel')) || 0;
    if (!name || level <= 0) return;               // skip blanks & project-summary row
    const isMs = first(t, 'Milestone') === '1';
    const isSummary = first(t, 'Summary') === '1';
    let days = isMs ? 0 : durToDays(first(t, 'Duration'), hpd);
    if (isSummary) days = 0;
    else if (!isMs) days = Math.max(1, days);
    const uidStr = first(t, 'UID');
    let uid = parseInt(uidStr);
    const preds = [...t.getElementsByTagNameNS('*', 'PredecessorLink')]
      .map(l => parseInt(first(l, 'PredecessorUID'))).filter(n => !isNaN(n));
    out.push({ id: uid, name, level: Math.min(6, level), days, preds, res: taskRes[uidStr] || '' });
  });
  if (!out.length) throw new Error('no tasks found in the file');

  // guarantee unique numeric ids without breaking predecessor references
  let mx = Math.max(0, ...out.map(t => (isNaN(t.id) ? 0 : t.id)));
  out.forEach(t => { if (isNaN(t.id)) t.id = ++mx; });

  return { name: projName, hpd, start: startAttr ? startAttr.slice(0, 10) : '', tasks: out };
}

function importFile(ev) {
  const f = ev.target.files && ev.target.files[0];
  ev.target.value = '';
  if (!f) return;
  if (/\.mpp$/i.test(f.name)) {
    toast('.mpp is binary — in MS Project use File ▸ Save As ▸ XML, then import that .xml');
    return;
  }
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const data = importMSPDI(String(e.target.result));
      document.getElementById('projName').value = data.name;
      if (data.start) document.getElementById('projStart').value = data.start;
      if (data.hpd) document.getElementById('hoursDay').value = data.hpd;
      tasks = data.tasks.map(t => ({ id: t.id, name: t.name, level: Math.max(1, t.level), days: t.days, preds: t.preds, res: t.res }));
      nextId = Math.max(0, ...tasks.map(t => t.id)) + 1;
      _schedCache = null;
      render();
      showView('build');
      toast('Imported ' + tasks.length + ' tasks from ' + f.name + ' — now editable');
    } catch (err) {
      toast('Import failed: ' + err.message);
    }
  };
  reader.onerror = () => toast('Could not read the file');
  reader.readAsText(f);
}

